package edu.synergy.algorithms.finalproject;
import java.util.*;
public final class MiniJson { private final String s;private int p;private MiniJson(String s){this.s=s;} /** Time: O(k). */ public static Object parse(String s){MiniJson j=new MiniJson(s);Object v=j.value();j.ws();if(j.p!=s.length())throw new IllegalArgumentException("Trailing JSON");return v;} private Object value(){ws();if(p>=s.length())throw err();char c=s.charAt(p);if(c=='{')return object();if(c=='[')return array();if(c=='\"')return string();if(c=='t'&&take("true"))return true;if(c=='f'&&take("false"))return false;if(c=='n'&&take("null"))return null;return number();} private Map<String,Object> object(){p++;Map<String,Object>m=new LinkedHashMap<>();ws();if(ch('}'))return m;do{ws();String k=string();ws();need(':');m.put(k,value());ws();if(ch('}'))return m;need(',');}while(true);} private List<Object> array(){p++;List<Object>a=new ArrayList<>();ws();if(ch(']'))return a;do{a.add(value());ws();if(ch(']'))return a;need(',');}while(true);} private String string(){need('"');StringBuilder b=new StringBuilder();while(p<s.length()){char c=s.charAt(p++);if(c=='"')return b.toString();if(c=='\\'){char e=s.charAt(p++);b.append(switch(e){case '"','\\','/'->e;case 'b'->'\b';case 'f'->'\f';case 'n'->'\n';case 'r'->'\r';case 't'->'\t';case 'u'->{int code=Integer.parseInt(s.substring(p,p+4),16);p+=4;yield(char)code;}default->throw err();});}else b.append(c);}throw err();} private Number number(){int start=p;if(ch('-')){}while(p<s.length()&&Character.isDigit(s.charAt(p)))p++;boolean fp=false;if(p<s.length()&&s.charAt(p)=='.'){fp=true;p++;while(p<s.length()&&Character.isDigit(s.charAt(p)))p++;}String n=s.substring(start,p);return fp?Double.parseDouble(n):Long.parseLong(n);} private boolean take(String x){if(s.startsWith(x,p)){p+=x.length();return true;}return false;} private boolean ch(char c){if(p<s.length()&&s.charAt(p)==c){p++;return true;}return false;} private void need(char c){if(!ch(c))throw err();} private void ws(){while(p<s.length()&&Character.isWhitespace(s.charAt(p)))p++;} private IllegalArgumentException err(){return new IllegalArgumentException("Invalid JSON at "+p);} /** Time: O(length). */ public static String quote(String v){return "\""+v.replace("\\","\\\\").replace("\"","\\\"").replace("\n","\\n")+"\"";}
}
